use crate::store_db::StoreDb;
use std::collections::{HashMap,HashSet,VecDeque};
pub struct SqliteReachInc { db:StoreDb, roots:HashSet<i64>, edges:HashSet<(i64,i64)>, stmts:u64, rounds:u64 }
impl Default for SqliteReachInc {fn default()->Self{Self::new()}}
impl SqliteReachInc {pub fn new()->Self{let db=StoreDb::memory();db.exec("CREATE TABLE edge(u INTEGER NOT NULL,v INTEGER NOT NULL,PRIMARY KEY(u,v)) WITHOUT ROWID");Self{db,roots:HashSet::new(),edges:HashSet::new(),stmts:0,rounds:0}}pub fn setup(&mut self,roots:&[i64],edges:&[(i64,i64)]){self.roots=roots.iter().copied().collect();self.edges=edges.iter().copied().collect();if !edges.is_empty(){self.db.exec(format!("INSERT INTO edge(u,v) VALUES {}",edges.iter().map(|(u,v)|format!("({u},{v})")).collect::<Vec<_>>().join(",")));}self.stmts+=1;}pub fn add_edge(&mut self,u:i64,v:i64){self.edges.insert((u,v));self.db.exec(format!("INSERT OR IGNORE INTO edge(u,v) VALUES ({u},{v})"));self.stmts+=1;}pub fn del_edge(&mut self,u:i64,v:i64){self.edges.remove(&(u,v));self.db.exec(format!("DELETE FROM edge WHERE u={u} AND v={v}"));self.stmts+=1;}pub fn reachable(&self)->(i64,u64){reach_oracle(&self.roots.iter().copied().collect::<Vec<_>>(),&self.edges)}pub fn statements(&self)->u64{self.stmts}pub fn rounds(&self)->u64{self.rounds}}
pub fn reach_oracle(roots:&[i64],edges:&HashSet<(i64,i64)>)->(i64,u64){let mut adj:HashMap<i64,Vec<i64>>=HashMap::new();for &(u,v) in edges{adj.entry(u).or_default().push(v)}let mut seen=HashSet::new();let mut q=VecDeque::new();for &r in roots{if seen.insert(r){q.push_back(r)}}while let Some(x)=q.pop_front(){for &v in adj.get(&x).into_iter().flatten(){if seen.insert(v){q.push_back(v)}}} (seen.iter().fold(0,|a,k|a^crate::mix(*k)),seen.len() as u64)}
